def _local_handle():
    """llama-cpp-python GGUF loader for offline mode. TODO Off-Grid."""
    raise NotImplementedError("Off-Grid: implement local Qwen via llama-cpp-python")


def generate(
    system_prompt: str,
    user_prompt: str,
    *,
    max_new_tokens: int = 1024,
    temperature: float = 0.7,
) -> str:
